import{_ as a,o as t,c as o,ai as n}from"./chunks/framework.C_v2XVcg.js";const b=JSON.parse('{"title":"Solus Documentation","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"docs/index.md","filePath":"docs/index.md"}'),s={name:"docs/index.md"};function i(l,e,r,d,h,u){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="solus-documentation" tabindex="-1">Solus Documentation <a class="header-anchor" href="#solus-documentation" aria-label="Permalink to “Solus Documentation”">​</a></h1><p>Welcome to the solus docs! This is the place you&#39;ll find handwritten guides for not only how to write the language but in depth documentation of the standard library and (soon) the C API where you can find out how solus can be integrated into your C programs. You can use either this landing page or the navigation sidebar to make your way around the docs.</p><h2 id="📙-nbsp-nbsp-solus-handbook" tabindex="-1">📙  Solus Handbook <a class="header-anchor" href="#📙-nbsp-nbsp-solus-handbook" aria-label="Permalink to “📙&amp;nbsp;&amp;nbsp;Solus Handbook”">​</a></h2><p>The solus handbook is a detailed quickstart guide to getting started with solus. It covers everything you need to know from basic values to the unique features of my language and how to use them to write the best solus. It&#39;s recommended that you have some basic programming experience going in, but it shouldn&#39;t be required to get the gist of it.</p><h3 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to “Table of Contents”">​</a></h3><ul><li><a href="/docs/handbook/introduction.html">Introduction</a></li><li><a href="/docs/handbook/the-basics.html">The Basics</a></li><li><a href="/docs/handbook/the-language.html">The Language</a></li><li><a href="/docs/handbook/idiomatic-solus.html">Idiomatic Solus</a></li></ul><h2 id="🧰-nbsp-nbsp-standard-library" tabindex="-1">🧰  Standard Library <a class="header-anchor" href="#🧰-nbsp-nbsp-standard-library" aria-label="Permalink to “🧰&amp;nbsp;&amp;nbsp;Standard Library”">​</a></h2><p>Solus includes a standard library which is <em>optional</em> in solus environments, but it&#39;s extremely unlikely you&#39;ll be interacting with one that doesn&#39;t use the std. This section documents the different modules of the standard library and how they&#39;re properly used. Any good solus program makes heavy use of the standard library, especially the builtin functions.</p><h3 id="table-of-contents-1" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents-1" aria-label="Permalink to “Table of Contents”">​</a></h3><ul><li><a href="/docs/std/builtin.html">Builtin</a></li><li><a href="/docs/std/io.html">IO</a></li><li><a href="/docs/std/string.html">String</a></li><li><a href="/docs/std/obj.html">Object</a></li><li><a href="/docs/std/math.html">Math</a></li></ul>',10)])])}const m=a(s,[["render",i]]);export{b as __pageData,m as default};
